impl Item {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::Glyphs(v) => {
                out.push_str("Glyphs(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Rect(v) => {
                out.push_str("Rect(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Line(v) => {
                out.push_str("Line(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Image(v) => {
                out.push_str("Image(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Clip(v) => {
                out.push_str("Clip(");
                let v = *v;
                uo_codec::dump::f64(out, v);
                out.push(')');
            }
            Self::Path(v) => {
                out.push_str("Path(");
                out.push('[');
                for (i0, e0) in v.iter().copied().enumerate() {
                    if i0 > 0 { out.push(','); }
                    uo_codec::dump::f64(out, e0);
                }
                out.push(']');
                out.push(')');
            }
            Self::Group(v) => {
                out.push_str("Group(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Label(v) => {
                out.push_str("Label(");
                let v = *v;
                uo_codec::dump::utf16(out, t.sym_units(v));
                out.push(')');
            }
            Self::Count(v) => {
                out.push_str("Count(");
                let v = *v;
                uo_codec::dump::u(out, v);
                out.push(')');
            }
            Self::Flag(v) => {
                out.push_str("Flag(");
                let v = *v;
                out.push_str(if v { "true" } else { "false" });
                out.push(')');
            }
            Self::Dashes(v) => {
                out.push_str("Dashes(");
                let v = *v;
                v.dump(out, t);
                out.push(')');
            }
            Self::Pop => out.push_str("Pop"),
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(12) {
            0 => Self::Glyphs(GlyphRun::random(rng, b, depth + 1)),
            1 => Self::Rect(Rect::random(rng, b, depth + 1)),
            2 => Self::Line(Line::random(rng, b, depth + 1)),
            3 => Self::Image(ImageItem::random(rng, b, depth + 1)),
            4 => Self::Clip(rng.f64_edge()),
            5 => Self::Path({ let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| rng.f64_edge()).collect::<Vec<_>>() }),
            6 => Self::Group(Group::random(rng, b, depth + 1)),
            7 => Self::Label(rng.below(b.sym)),
            8 => Self::Count(rng.i32_edge()),
            9 => Self::Flag(rng.bool()),
            10 => Self::Dashes(Dash::random(rng, b, depth + 1)),
            _ => Self::Pop,
        }
    }
}

